import time

class RequestTimeLoggingMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        start_time = time.time()

        response = self.get_response(request)

        duration = time.time() - start_time
        print(f"[{request.method}] {request.path} took {duration:.2f} seconds.")

        return response
MIDDLEWARE = [
    ...
    'yourapp.middleware.RequestTimeLoggingMiddleware',
]
from django.http import HttpResponse
from django.conf import settings

class MaintenanceModeMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        # Enable maintenance mode with a setting
        if getattr(settings, 'MAINTENANCE_MODE', False):
            if not request.user.is_authenticated or not request.user.is_superuser:
                return HttpResponse("<h1>Site Under Maintenance</h1>", status=503)
        return self.get_response(request)
MIDDLEWARE = [
    ...
    'yourapp.middleware.MaintenanceModeMiddleware',
]

# Enable this flag to activate maintenance mode
